package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
import java.util.*; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.crypto.password.PasswordEncoder;
import com.tuap.backend.dominio.entidades.*; import com.tuap.backend.persistencia.*;
class LocalIdentityCreationServiceTest {
 @Mock AuthIdentityDAO identities; @Mock IdentityResolver users; @Mock ClienteDAO clientes; @Mock EntrenadorDAO entrenadores; @Mock ReauthenticationService reauth; @Mock PasswordEncoder passwords; @InjectMocks LocalIdentityCreationService service;
 final UUID id=UUID.randomUUID(); final AuthenticatedUser user=new AuthenticatedUser(id,"user@nextfit.test",Role.CLIENTE);
 @BeforeEach void init(){MockitoAnnotations.openMocks(this);when(users.findByIdAndRole(id,Role.CLIENTE)).thenReturn(Optional.of(user));when(identities.lockActiveByUserIdAndRole(id,Role.CLIENTE)).thenReturn(List.of());when(identities.existsByUserIdAndRoleAndProviderAndActiveTrue(id,Role.CLIENTE,AuthProvider.LOCAL)).thenReturn(false);Cliente c=new Cliente();c.setContrasena(null);when(clientes.findById(id)).thenReturn(Optional.of(c));when(passwords.encode("valid-pass")).thenReturn("bcrypt");}
 @Test void createsLocalAfterExplicitReauth(){AuthIdentityLinkResponse result=service.create(user,new LocalIdentityCreationRequest("reauth","valid-pass"));verify(reauth).consumeForCreateLocal(user,"reauth");verify(clientes).save(argThat(c->"bcrypt".equals(c.getContrasena())));ArgumentCaptor<AuthIdentity> cap=ArgumentCaptor.forClass(AuthIdentity.class);verify(identities).saveAndFlush(cap.capture());assertEquals(AuthProvider.LOCAL,cap.getValue().getProvider());assertEquals(id.toString(),cap.getValue().getProviderSubject());assertEquals(AuthIdentityLinkResponse.Status.LINKED,result.status());}
 @Test void existingLocalCannotChangePassword(){when(identities.existsByUserIdAndRoleAndProviderAndActiveTrue(id,Role.CLIENTE,AuthProvider.LOCAL)).thenReturn(true);assertThrows(LocalIdentityAlreadyExistsException.class,()->service.create(user,new LocalIdentityCreationRequest("r","valid-pass")));verifyNoInteractions(reauth);verify(clientes,never()).save(any());}
 @Test void invalidPasswordDoesNotConsumeToken(){assertThrows(InvalidPasswordException.class,()->service.create(user,new LocalIdentityCreationRequest("r","short")));verifyNoInteractions(reauth);verify(identities,never()).saveAndFlush(any());}
 @Test void wrongReauthDoesNotPersist(){doThrow(new InvalidReauthenticationTokenException()).when(reauth).consumeForCreateLocal(user,"bad");assertThrows(InvalidReauthenticationTokenException.class,()->service.create(user,new LocalIdentityCreationRequest("bad","valid-pass")));verify(clientes,never()).save(any());verify(identities,never()).saveAndFlush(any());}
}
